import math

# From treasury_bulletin_1985_03_page_22.txt - 1984 data
judiciary_1984 = {
    'Jan': 84, 'Feb': 89, 'Mar': 63, 'Apr': 74, 'May': 62, 'Jun': 93,
    'Jul': 65, 'Aug': 79, 'Sep': 69, 'Oct': 79, 'Nov': 67, 'Dec': 96
}

# From treasury_bulletin_1986_03_page_26.txt - 1985 data
judiciary_1985 = {
    'Jan': 66, 'Feb': 60, 'Mar': 59, 'Apr': 119, 'May': 75, 'Jun': 63,
    'Jul': 74, 'Aug': 103, 'Sep': 66, 'Oct': 98, 'Nov': 74, 'Dec': 102
}

# From treasury_bulletin_1987_03_page_24.txt - 1986 data
judiciary_1986 = {
    'Jan': 76, 'Feb': 109, 'Mar': 74, 'Apr': 129, 'May': 75, 'Jun': 71,
    'Jul': 70, 'Aug': 106, 'Sep': 87, 'Oct': 73, 'Nov': 73, 'Dec': 113
}

# From treasury_bulletin_1988_03_page_36.txt - 1987 data (Jan-Mar only)
judiciary_1987_jan_mar = {
    'Jan': 79, 'Feb': 76, 'Mar': 110
}

# Combine all monthly values from Jan 1984 to Mar 1987
months = []
for m in ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec']:
    months.append(judiciary_1984[m])
for m in ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec']:
    months.append(judiciary_1985[m])
for m in ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec']:
    months.append(judiciary_1986[m])
months.extend([judiciary_1987_jan_mar['Jan'], judiciary_1987_jan_mar['Feb'], judiciary_1987_jan_mar['Mar']])

print('Number of months:', len(months))
print('Monthly values:', months)

# Calculate geometric mean
product = 1
for v in months:
    product *= v

geometric_mean = product ** (1/len(months))
print('Geometric mean:', geometric_mean)
print('In millions (rounded to nearest thousandth):', round(geometric_mean, 3))
